-- ============================================
-- MIGRATION: Add features column + seed services data
-- Run this in your Supabase SQL Editor
-- ============================================

-- Add features column (PostgreSQL TEXT array)
ALTER TABLE services ADD COLUMN IF NOT EXISTS features TEXT[];

-- Seed all 19 existing services with their images and data
-- Uses ON CONFLICT to avoid duplicates if services already exist

ON CONFLICT (slug) DO UPDATE SET
  description = EXCLUDED.description,
  long_description = EXCLUDED.long_description,
  icon = EXCLUDED.icon,
  image_url = EXCLUDED.image_url,
  features = EXCLUDED.features,
  sort_order = EXCLUDED.sort_order,
  updated_at = NOW();
